function sumFor(name, year, month){
  const sh = ss.getSheetByName('Sales Detail');
  const lastRow = sh.getLastRow();
  const data = sh.getRange(8,5,lastRow-7,12).getValues(); // E:P
  let total = 0;
  for (const row of data){
    const y = row[0];      // E
    const m = row[1];      // F
    const cust = row[4];   // I
    const type = row[6];   // K
    const amt = row[11];   // P
    if (cust === name && y === year && m === month && type === 'Sod' && typeof amt === 'number') total += amt;
  }
  return total;
}
